@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&display=swap');
:root{color-scheme:dark;--bg:#10131c;--panel:#191e2a;--muted:#8d96a8;--line:#2b3240;--mint:#a8f0ce;--pink:#ff8b89;--gold:#ffcb83}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 42% 3%,#202638 0,#121722 48%,#0e1118 100%);color:#f4f4f5;font-family:'DM Sans',system-ui,sans-serif;display:flex;justify-content:center;align-items:center;padding:24px}.game-shell{width:min(1190px,100%);}.topbar{height:60px;display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}.brand{display:flex;align-items:center;gap:12px}.brand-mark{color:var(--mint);font-size:30px;text-shadow:0 0 20px #a8f0ce50}.brand h1{font-size:14px;letter-spacing:2.4px;margin:0;font-weight:800}.brand p{font:10px 'DM Mono',monospace;letter-spacing:1.4px;color:#929bad;margin:3px 0 0}.live-dot,.pulse{display:inline-block;width:6px;height:6px;border-radius:50%;background:#a8f0ce;box-shadow:0 0 10px #a8f0ce;margin-left:4px}.top-meta{display:flex;align-items:center;gap:17px;color:#b3b9c7;font:11px 'DM Mono',monospace}.tag{border:1px solid #394150;border-radius:20px;padding:7px 12px;color:#c5ccda;letter-spacing:1px}.time{font-size:13px}.game-layout{display:grid;grid-template-columns:minmax(0,1.63fr) minmax(320px,.82fr);border:1px solid #303747;border-radius:13px;overflow:hidden;background:#171c27;box-shadow:0 25px 80px #0007}.stage-wrap{position:relative;min-height:580px;background:#111522;overflow:hidden}.stage-wrap canvas{display:block;width:100%;height:100%;position:absolute;inset:0}.scene-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,#0b101933,transparent 23%,transparent 73%,#0b101966)}.stage-label,.stage-hint{position:absolute;z-index:2;bottom:19px;color:#d4d9e3;font:10px 'DM Mono',monospace;letter-spacing:1.3px}.stage-label{left:20px}.stage-label .pulse{margin:0 8px 0 0;width:5px;height:5px}.separator{color:#697386;margin:0 7px}.stage-hint{right:20px;color:#aab1be}.crosshair{display:none;position:absolute;z-index:3;pointer-events:none;transform:translate(-50%,-50%);width:26px;height:26px;border:1px solid #a8f0ceaa;border-radius:50%;box-shadow:0 0 13px #a8f0ce66}.crosshair:before,.crosshair:after{content:'';position:absolute;background:#d6ffeb;left:50%;top:50%;transform:translate(-50%,-50%)}.crosshair:before{width:1px;height:36px}.crosshair:after{width:36px;height:1px}.crosshair i{position:absolute;inset:9px;border-radius:50%;background:#eafff3}.toast{position:absolute;top:24px;left:50%;transform:translate(-50%,-8px);opacity:0;z-index:4;padding:9px 13px;border:1px solid #ffffff26;border-radius:20px;background:#111822d9;color:#effff5;font:10px 'DM Mono',monospace;letter-spacing:.8px;transition:.2s;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.panel{padding:25px 25px 17px;border-left:1px solid #303747;background:linear-gradient(155deg,#1d2330,#171c27 60%);}.panel-heading{display:flex;justify-content:space-between;align-items:center}.eyebrow{font:10px 'DM Mono',monospace;letter-spacing:1.5px;color:#9da6b6}.panel h2{font-size:24px;letter-spacing:-.7px;margin:5px 0 0}.moon{font-size:25px;color:var(--gold);width:43px;height:43px;border-radius:13px;display:grid;place-items:center;background:#ffcb8312;border:1px solid #ffcb8328}.intro{font-size:12px;color:#aab2c0;line-height:1.6;margin:11px 0 16px}.objective{height:56px;border:1px solid #373f4d;background:#222937;border-radius:8px;display:flex;align-items:center;padding:0 12px;gap:10px}.objective-icon{color:var(--gold);font-size:18px}.objective b,.volume-row b,.dad-status b{display:block;font-size:11px}.objective small,.volume-row small,.dad-status small{display:block;color:#9aa3b1;font-size:10px;margin-top:3px}.score{margin-left:auto;font:16px 'DM Mono',monospace;color:#eaf9f0}.score small{font-size:10px;color:#8e98a8}.meter-block{margin-top:19px}.meter-head,.meter-foot{display:flex;justify-content:space-between;align-items:center;font:9px 'DM Mono',monospace;letter-spacing:1px}.meter-head{color:#d6dae2}.meter-head span:last-child{color:var(--mint)}.meter{height:9px;background:#303846;border-radius:8px;margin:9px 0 6px;position:relative;overflow:visible}.meter-fill{height:100%;width:8%;border-radius:8px;background:linear-gradient(90deg,#84dfbd,#f0d47a,#ff817e);transition:width .25s}.meter-tick{position:absolute;top:-3px;bottom:-3px;left:60%;width:1px;background:#ffe4a8aa}.meter-foot{color:#919aa9;letter-spacing:.1px;font:10px 'DM Sans',sans-serif}.meter-foot span:last-child{font-family:'DM Mono',monospace}.volume-row{display:flex;align-items:center;gap:10px;margin-top:17px;padding-bottom:15px;border-bottom:1px solid #303744}.vol-icon{width:31px;height:31px;display:grid;place-items:center;border-radius:8px;background:#a8f0ce13;color:var(--mint);font-size:17px}.vol-copy{flex:1}.remote-button{border:1px solid #46515e;border-radius:6px;background:#2c3542;color:#edf4f4;font:9px 'DM Mono',monospace;letter-spacing:.6px;padding:8px 10px;cursor:pointer;transition:.15s}.remote-button:hover,.remote-button:focus-visible{background:#405046;border-color:var(--mint)}.remote-button span{font-size:13px;color:var(--mint);vertical-align:-1px;margin-right:4px}.dad-status{display:flex;align-items:center;gap:10px;margin:14px 0 18px;padding:10px 11px;background:#202632;border:1px solid #303947;border-radius:8px;transition:.2s}.eye-icon{color:#91a1b7;font-size:19px}.dad-status div{flex:1}.dad-status b{color:#dce1e8}.dad-status small{font-size:9px}.status-pip{width:6px;height:6px;border-radius:50%;background:#8aa694}.dad-status.alert{border-color:#a76356;background:#382c31}.dad-status.alert .eye-icon,.dad-status.alert b{color:#ffaaa0}.dad-status.alert .status-pip{background:#ff8578;box-shadow:0 0 10px #ff8578}.controls-title{display:flex;justify-content:space-between;color:#cbd1da;font:9px 'DM Mono',monospace;letter-spacing:.7px;margin-bottom:9px}.controls-title span{color:#858fa0;font-size:8px}.controls-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:5px;margin-bottom:16px}.controls-grid>div{display:flex;flex-direction:column;align-items:center;gap:5px;color:#9ba4b2;font-size:9px}.controls-grid kbd,.start-button kbd{font:9px 'DM Mono',monospace;color:#e1e5eb;background:#303744;border:1px solid #4a5360;border-radius:4px;padding:4px 6px}.start-button{width:100%;height:42px;border:0;border-radius:7px;background:var(--mint);color:#12211b;font:800 10px 'DM Sans',sans-serif;letter-spacing:1px;cursor:pointer;box-shadow:0 5px 17px #a8f0ce1b;transition:transform .15s,filter .15s}.start-button:hover{filter:brightness(1.08);transform:translateY(-1px)}.start-button>span{margin-right:6px}.start-button kbd{float:right;margin-top:-3px;background:#78c7a6;border-color:#78c7a6;color:#102017}.fineprint{text-align:center;color:#828b99;font-size:9px;margin:10px 0 0}footer{height:40px;display:flex;align-items:center;justify-content:space-between;color:#929aaa;font:9px 'DM Mono',monospace;letter-spacing:.6px}footer span:first-child{color:#bcc5d0}footer button{border:0;background:transparent;color:#a8f0ce;font:9px 'DM Mono',monospace;letter-spacing:.8px;cursor:pointer}.modal{position:fixed;inset:0;z-index:10;background:#090c12c9;backdrop-filter:blur(7px);display:grid;place-items:center;padding:20px}.modal.hidden{display:none}.modal-card{width:min(390px,100%);padding:33px 30px 26px;background:#1a202b;border:1px solid #424a57;border-radius:14px;text-align:center;box-shadow:0 30px 100px #0009}.modal-icon{font-size:37px;color:var(--gold);margin-bottom:12px}.modal-card h2{font-size:27px;margin:8px 0}.modal-card p{color:#aab2c0;font-size:13px;line-height:1.6;margin:0 0 23px}.text-button{display:block;background:none;border:0;color:#aab2c0;font:10px 'DM Mono',monospace;margin:14px auto 0;cursor:pointer}.shake{animation:shake .3s}@keyframes shake{25%{transform:translateX(-4px)}70%{transform:translateX(4px)}}
@media(max-width:850px){body{padding:14px}.game-layout{grid-template-columns:minmax(0,1fr) 310px}.stage-wrap{min-height:530px}.panel{padding:20px 17px 15px}.panel h2{font-size:21px}.controls-title span{display:none}}
@media(max-width:680px){body{padding:10px;align-items:flex-start}.topbar{height:47px;margin-bottom:9px}.game-layout{display:flex;flex-direction:column}.stage-wrap{height:auto;min-height:0;aspect-ratio:1.12 / 1}.panel{border-left:0;border-top:1px solid #303747;padding:18px}.intro{margin:8px 0 13px}.panel h2{font-size:20px}.volume-row{margin-top:13px}.dad-status{margin:11px 0 14px}.controls-grid{margin-bottom:12px}footer{font-size:8px;gap:6px}footer span:nth-child(2){display:none}.stage-hint{font-size:8px}.stage-label{font-size:9px}}
@media(max-height:760px) and (min-width:681px){body{padding:12px}.stage-wrap{min-height:500px}.panel{padding-top:17px;padding-bottom:12px}.intro{margin:8px 0 11px}.dad-status{margin:10px 0 13px}.controls-grid{margin-bottom:11px}}

(() => {
  const canvas = document.getElementById('scene');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const ui = { score: $('score'), fill: $('noiseFill'), noise: $('noiseNum'), noiseLabel: $('noiseLabel'), vol: $('volumeLabel'), volIcon: $('volumeIcon'), dad: $('dadStatus'), toast: $('toast'), start: $('startButton'), remote: $('remoteButton'), cross: $('crosshair'), modal: $('modal'), modalTitle: $('modalTitle'), modalText: $('modalText'), modalEyebrow: $('modalEyebrow'), modalIcon: $('modalIcon'), hint: $('stageHint') };
  const state = { running:false, ended:false, score:0, noise:8, volume:2, dadUntil:0, lastShot:0, lastRemote:0, startedAt:0, timeLeft:90, toastUntil:0, mouse:{x:.5,y:.5}, targets:[], particles:[], padWasDown:false, padRemoteWasDown:false, stars:[] };
  const W=1000,H=700;
  for(let i=0;i<34;i++) state.stars.push({x:Math.random(),y:Math.random(),r:Math.random()*1.5+.3,a:Math.random()*.55+.2});
  function resize(){const r=canvas.getBoundingClientRect();const d=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.round(r.width*d));canvas.height=Math.max(1,Math.round(r.height*d));ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0)}
  new ResizeObserver(resize).observe(canvas); resize();
  function rounded(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
  function poly(points,fill,stroke){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
  function drawRoom(t){
    const wall=ctx.createLinearGradient(0,0,0,500);wall.addColorStop(0,'#262d40');wall.addColorStop(.7,'#252838');wall.addColorStop(1,'#302b35');ctx.fillStyle=wall;ctx.fillRect(0,0,W,H);
    // Midnight window and moonlit curtains
    rounded(79,75,228,175,8,'#161c2c','#4d5264');ctx.fillStyle='#19263a';ctx.fillRect(90,86,206,153);ctx.fillStyle='#293f5a';ctx.fillRect(92,88,201,149);
    for(const s of state.stars){ctx.globalAlpha=s.a;ctx.fillStyle='#d5e7ff';ctx.beginPath();ctx.arc(92+s.x*201,88+s.y*149,s.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
    ctx.fillStyle='#f3dfb2';ctx.beginPath();ctx.arc(253,120,21,0,Math.PI*2);ctx.fill();ctx.fillStyle='#293f5a';ctx.beginPath();ctx.arc(264,111,19,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle='#59657a';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(192,87);ctx.lineTo(192,239);ctx.moveTo(91,161);ctx.lineTo(294,161);ctx.stroke();
    poly([[65,62],[322,62],[307,80],[82,80]],'#4b3b49');poly([[65,62],[82,80],[82,259],[65,276]],'#483b49');poly([[322,62],[307,80],[307,259],[322,276]],'#443846');
    // wall trim and art
    ctx.fillStyle='#443d4a';ctx.fillRect(0,465,1000,9);ctx.fillStyle='#393744';ctx.fillRect(0,476,1000,4);
    rounded(394,93,76,103,4,'#423743','#776273');rounded(402,101,60,87,2,'#304356');poly([[405,173],[420,131],[434,154],[446,117],[459,174]],'#5a7880');ctx.fillStyle='#e7bb83';ctx.beginPath();ctx.arc(448,123,6,0,Math.PI*2);ctx.fill();
    rounded(500,145,85,54,4,'#403344','#675268');ctx.fillStyle='#bc8b92';ctx.beginPath();ctx.arc(542,172,18,Math.PI,0);ctx.lineTo(560,185);ctx.lineTo(525,185);ctx.closePath();ctx.fill();
    // door opening; Dad appears here on each sound cue
    poly([[729,105],[922,105],[922,476],[729,476]],'#171b28','#5c5360');poly([[744,119],[906,119],[906,470],[744,470]],'#302b38');
    ctx.fillStyle='#191c28';ctx.fillRect(758,130,135,340);
    const peek=state.dadUntil>performance.now()?1:0;const phase=peek?Math.min(1,(state.dadUntil-performance.now())/330):0;const dx=peek?Math.sin((performance.now()/210))*2:0;
    if(peek){drawDad(836+dx,236,phase)}else{ctx.fillStyle='#463749';ctx.fillRect(747,116,14,355);ctx.fillStyle='#d9ad70';ctx.beginPath();ctx.arc(884,292,5,0,Math.PI*2);ctx.fill()}
    // side table and lamp
    poly([[56,371],[206,371],[235,395],[38,395]],'#563c42');poly([[38,395],[235,395],[218,460],[55,460]],'#3a303c');ctx.fillStyle='#4b3b47';ctx.fillRect(106,395,12,65);ctx.fillRect(162,395,12,65);
    poly([[103,277],[154,277],[174,334],[83,334]],'#d6ad82');ctx.fillStyle='#ffe0a6';ctx.globalAlpha=.16;ctx.beginPath();ctx.arc(129,331,100,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#e6c691';ctx.fillRect(122,334,14,40);rounded(115,370,28,8,3,'#57404a');
    // floor perspective
    poly([[0,478],[1000,478],[1000,700],[0,700]],'#252330');const floor=ctx.createLinearGradient(0,478,0,700);floor.addColorStop(0,'#403542');floor.addColorStop(1,'#262632');ctx.fillStyle=floor;ctx.fillRect(0,478,1000,222);
    ctx.strokeStyle='#574451';ctx.lineWidth=1;for(let i=0;i<9;i++){const y=490+i*i*2.35;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(1000,y);ctx.stroke()}for(let x=-100;x<1200;x+=140){ctx.beginPath();ctx.moveTo(500,477);ctx.lineTo(x,700);ctx.stroke()}
    // rug
    poly([[260,535],[742,535],[898,700],[105,700]],'#34303c','#51404a');poly([[300,552],[710,552],[820,686],[180,686]],'#393541');
    // TV cabinet
    poly([[290,364],[730,364],[777,392],[258,392]],'#684850');poly([[258,392],[777,392],[760,526],[278,526]],'#46343d');poly([[278,526],[760,526],[745,540],[290,540]],'#312c38');
    ctx.fillStyle='#533d45';ctx.fillRect(296,397,438,5);ctx.fillStyle='#2d2934';ctx.fillRect(307,410,193,90);ctx.fillRect(516,410,211,90);ctx.fillStyle='#73535b';ctx.fillRect(306,501,423,4);
    // TV silhouette and frame
    poly([[339,145],[682,145],[703,160],[703,359],[319,359],[319,160]],'#11151f','#637080');poly([[329,156],[691,156],[691,346],[329,346]],'#080f1c','#697483');
    drawTv(t);
    // PS5-style controller resting in foreground
    ctx.save();ctx.translate(515,584);ctx.rotate(-.07);ctx.fillStyle='#202532';ctx.strokeStyle='#68707b';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-57,-6);ctx.quadraticCurveTo(-61,-27,-34,-29);ctx.lineTo(-14,-21);ctx.lineTo(14,-21);ctx.lineTo(34,-29);ctx.quadraticCurveTo(61,-27,57,-6);ctx.lineTo(47,25);ctx.quadraticCurveTo(41,36,31,26);ctx.lineTo(17,9);ctx.lineTo(-17,9);ctx.lineTo(-31,26);ctx.quadraticCurveTo(-41,36,-47,25);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#9da6b6';ctx.fillRect(-28,-12,16,3);ctx.fillRect(-22,-18,3,15);ctx.fillStyle='#a8f0ce';ctx.beginPath();ctx.arc(23,-10,3,0,7);ctx.fill();ctx.fillStyle='#ff8b89';ctx.beginPath();ctx.arc(34,-3,3,0,7);ctx.fill();ctx.fillStyle='#9ca5b4';ctx.beginPath();ctx.arc(0,-17,3,0,7);ctx.fill();ctx.restore();
  }
  function drawDad(x,y,phase){ctx.save();ctx.globalAlpha=.55+.45*phase;ctx.fillStyle='#1b1d29';ctx.beginPath();ctx.ellipse(x,y+98,50,12,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#31303c';ctx.beginPath();ctx.moveTo(x-40,y+95);ctx.lineTo(x-35,y+21);ctx.quadraticCurveTo(x,y-4,x+35,y+21);ctx.lineTo(x+43,y+95);ctx.fill();ctx.fillStyle='#c89c80';ctx.beginPath();ctx.ellipse(x,y+5,28,34,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#40323a';ctx.beginPath();ctx.ellipse(x,y-11,30,18,0,Math.PI,Math.PI*2);ctx.fill();ctx.fillRect(x-30,y-8,10,11);ctx.fillRect(x+20,y-8,10,11);ctx.fillStyle='#2a2731';ctx.beginPath();ctx.ellipse(x,y+14,11,5,0,0,Math.PI);ctx.fill();ctx.fillStyle='#fff0cc';ctx.beginPath();ctx.arc(x-10,y+5,3,0,7);ctx.arc(x+10,y+5,3,0,7);ctx.fill();ctx.fillStyle='#35404b';ctx.fillRect(x-51,y+29,13,51);ctx.fillRect(x+38,y+29,13,51);ctx.restore()}
  function drawTv(t){
    const x=339,y=156,w=342,h=190;const grad=ctx.createLinearGradient(x,y,x+w,y+h);grad.addColorStop(0,'#152c47');grad.addColorStop(1,'#1c1640');ctx.fillStyle=grad;ctx.fillRect(x,y,w,h);
    // arcade horizon
    ctx.fillStyle='#171d38';ctx.beginPath();ctx.moveTo(x,y+115);ctx.lineTo(x+w/2,y+70);ctx.lineTo(x+w,y+115);ctx.lineTo(x+w,y+h);ctx.lineTo(x,y+h);ctx.fill();
    ctx.strokeStyle='#4e4c96';ctx.lineWidth=1;for(let i=0;i<6;i++){let yy=y+110+i*i*3;ctx.beginPath();ctx.moveTo(x,yy);ctx.lineTo(x+w,yy);ctx.stroke()}for(let i=-5;i<=5;i++){ctx.beginPath();ctx.moveTo(x+w/2,y+88);ctx.lineTo(x+w/2+i*44,y+h);ctx.stroke()}
    ctx.fillStyle='#f7d88e';ctx.font='bold 11px monospace';ctx.fillText('STAR BLASTER',x+13,y+20);ctx.fillStyle='#b9cdfa';ctx.font='9px monospace';ctx.fillText('SCORE '+String(state.score).padStart(2,'0'),x+w-87,y+20);
    if(!state.running&&!state.ended){ctx.fillStyle='#d9e8ff';ctx.font='bold 14px monospace';ctx.textAlign='center';ctx.fillText('MIDNIGHT ARCADE',x+w/2,y+57);ctx.font='9px monospace';ctx.fillStyle='#a8f0ce';ctx.fillText('PRESS START TO PLAY',x+w/2,y+74);ctx.textAlign='left'}
    // targets
    for(const a of state.targets){const xx=x+a.x*w, yy=y+a.y*h, pulse=1+Math.sin(t/170+a.phase)*.1;ctx.save();ctx.translate(xx,yy);ctx.scale(pulse,pulse);ctx.shadowBlur=15;ctx.shadowColor=a.gold?'#ffcf83':'#a8f0ce';ctx.fillStyle=a.gold?'#ffcf83':'#a8f0ce';ctx.beginPath();ctx.arc(0,0,a.r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#24344c';ctx.beginPath();ctx.arc(0,0,a.r*.45,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(-a.r*.12,-a.r*.12,a.r*.13,0,7);ctx.fill();ctx.restore()}
    if(state.running&&state.targets.length===0){ctx.textAlign='center';ctx.fillStyle='#a9b5d5';ctx.font='9px monospace';ctx.fillText('LOOK ALIVE…',x+w/2,y+115);ctx.textAlign='left'}
    if(state.noise>38){ctx.fillStyle=`rgba(255,130,120,${Math.min(.18,(state.noise-38)/350)})`;ctx.fillRect(x,y,w,h)}
    // Screen glass glint
    ctx.fillStyle='#ffffff08';poly([[x+2,y+2],[x+100,y+2],[x+25,y+h-2],[x+2,y+h-2]],'#ffffff0a');
  }
  function spawnTarget(){state.targets.push({x:.18+Math.random()*.64,y:.23+Math.random()*.57,r:Math.random()>.8?12:9,phase:Math.random()*6,gold:Math.random()>.84,life:performance.now()+3800})}
  function showToast(txt){ui.toast.textContent=txt;ui.toast.classList.add('show');state.toastUntil=performance.now()+1100}
